Let $L:\mathbb{R}^d\to\mathbb{R}$ be lower bounded with continuous fourth-order partial derivatives and $\beta$-Lipschitz continuous third-order partial derivatives, for some constant $\beta > 0$.
Consider the iterates $\{z_n\}_{n=0}^{N-1}$ computed by Anti-PGD as in \eqref{eq:Anti-PGD_z_formulation}, where for each $n$ the noise coordinate $\xi^n_i$ follows a symmetric centered Bernoulli distribution with variance $\sigma^2$ (i.e., $\sigma$ and $-\sigma$ have probability $1/2$).
If we set $\epsilon>0$ small enough such that $\eta = \Theta(\epsilon/\sigma^2)<\frac{1}{\beta}$ and let $N = \Omega(\sigma^2\epsilon^{-2})$, then it holds true\footnote{The first version of this paper had a mistake in the proof of this result and did not include the $O(\sigma^3)$ error. We note that this correction comes with minor changes in the theorem assumptions.} that
\begin{equation}
    \mathbb{E}\left[\frac{1}{N}\sum_{n=0}^{N-1}\|\nabla \tilde L(z_{n})\|^2\right]\le O(\epsilon) + O(\sigma^3).
\end{equation}
\label{thm:implicit_reg}

\label{thm:pac}
Let $Q(w|w^*)$ be any distribution over the parameters, centered at the solution $w^*$ found by a gradient-based method. For any non-negative real number $\lambda$, with probability at least
$1-\delta$ one has
\vspace{-2mm}
\begin{align*}
    &L_{\rm true}(Q(w|w^*)) \le L(w^*) +\frac{\lambda}{2M} +\frac{1}{\lambda}\ln\left(\frac{1}{\delta}\right)\\& + \underbrace{L(Q(w|w^*))-L(w^*)}_{\text{expected sharpness}} +\frac{1}{\lambda} \operatorname{KL}[Q(w|w^*) || P(w)],
\end{align*}
where $L_{\rm true}$ is the generalization loss; $L(Q) := \mathbb{E}_{w \sim Q} L(w)$ and $L_{\rm true}(Q) := \mathbb{E}_{w \sim Q} L_{\rm true}(w)$; $P$ is a distribution over parameters; and $\operatorname{KL}$ denotes the Kullback-Leibler divergence.

Let $L:\mathbb{R}^{d+1}\to\mathbb{R}$ be the \emph{widening valley} loss from Eq.~\eqref{eq:def_wv}.
We start optimizing from a point $w_0=(u_0,0)$, where $\|u_0\|^2=D\gg 1$~(e.g. the solution found by gradient descent), around which we consider the domain $\mathcal{D}_\alpha :=\{(u,v) \in \mathbb{R}^{d+1}:  \|u\|^2\in(\alpha D,D/\alpha)\}$ for some fixed $\alpha \in (0,1)$.
We want to compare the long-term stochastic dynamics of PGD and Anti-PGD, as defined in Eqs.~\eqref{eq:def_PGD} and \eqref{eq:def_antiPGD}, in terms of where they exit $\mathcal{D}_\alpha$.
As a noise model, we assume that the i.i.d.~perturbations $\xi_n$ are distributed according to a symmetric centered Bernoulli distribution  (i.e., $\sigma$ and $-\sigma$ have probability $1/2$) whose variance $\sigma^2$ is upper bounded by $\sigma^2 \in\left(0, \min\left\{\tfrac{\alpha^3 D}{2},  \tfrac{D}{8\alpha}\right\} \right]$. 
As a step size, we set $\eta = \frac{\alpha}{2D}$ which, for both methods, leads to stable dynamics inside of $\mathcal{D}_\alpha$. We find that (on average) PGD and Anti-PGD exit through different sides of $\mathcal{D}_\alpha$:
\vspace{-2mm}
\begin{enumerate}
    \item {\bfseries In high dimensions, PGD diverges away from zero.} If $d \geq \frac{2}{\alpha^2}$, then it holds for any admissible  $\sigma^2$ that
    \begin{equation}  \label{eq:thm_wv_PGD}
        \lim_{n \to \infty} \mathbb{E}\left[ \| u_n \|^2 \right] \geq D/\alpha,
    \end{equation}
    where $u_n$ are the first $d$ coordinates of $w_n$ computed by PGD as in \eqref{eq:def_PGD}. 
    \item {\bfseries Independent of dimensions, Anti-PGD goes to zero.} For  any $d \in \mathbb{N}$, if we choose any admissible $\sigma^2$ such that $\sigma^2 \leq \frac{\alpha D}{2d}$, then
    \begin{equation} \label{eq:thm_wv_antiPGD}
        \lim_{n \to \infty} \mathbb{E}\left[ \| u_n \|^2 \right] \leq \alpha D,
    \end{equation}
    where $u_n$ are the first $d$ coordinates of $w_n$, computed by Anti-PGD as in \eqref{eq:def_antiPGD}. 
\end{enumerate}
\label{thm:main_tube}

\label{corollary:main_tube}
In the same setting as Thm.~\ref{thm:main_tube}, let $\eta = \frac{\alpha}{2D}$, $\sigma^2 \in\left(0, \min\left\{\tfrac{\alpha^3 D}{2},  \tfrac{D}{8\alpha},\frac{\alpha D}{2d}\right\} \right]$ and $d\ge\frac{2}{\alpha^2}$. If $\alpha\ll 1$, then
\begin{align*}
    &\lim_{n \to \infty} \mathbb{E}[\operatorname{Tr}(\nabla^2 L(w^{\rm anti}_n)))]
    \leq
    16 \alpha D \ll \mathbb{E}[\operatorname{Tr}(\nabla^2 L(w_0)))]\\
    &\lim_{n \to \infty} \mathbb{E}[\operatorname{Tr}(\nabla^2 L(w^{\text{un}}_n)))]\ge  \ D/\alpha \ \gg
    \mathbb{E}[\operatorname{Tr}(\nabla^2 L(w_0)))],
\end{align*}
where $w^{\text{un}}_n=(u_n,v_n)$ and $w^{\rm anti}_n=(u_n,v_n)$ are the weights computed by Anti-PGD and PGD respectively.

First, we observe that Eq.~\eqref{eq:z_n_dyn_by_dim} implies~--~in the considered case of Bernoulli perturbations $\xi_n$ with $(\xi_i^n)^2 = \sigma^2$ a.s.~--~that
\begin{equation}
    z^{i}_{n+1} - z^{i}_{n} = - \underbrace{\partial_i \eta L(z_{n}) - \partial_i  \eta\frac{\sigma^2}{2}\sum_{j}\partial^2_{jj} L(z_{n})}_{= \eta \partial_i \tilde{L}(z_n)\ \text{(Regularized Gradient)}} -\underbrace{\eta\sum_{j}\partial^2_{ij} L(z_{n})\xi_{n}^j - \frac{\eta}{2} \partial_i \sum_{j\ne k}\partial^2_{jk} L(z_{n})\xi_{n}^j\xi_{n}^k}_{\text{Mean-zero Perturbation}} + \underbrace{O(\eta\sigma^3)}_{\text{Expansion error (small)}}. \label{eq:writing_out_z_n_for_Ber}
\end{equation}
Since we assumed that $L$ has $\beta$-Lipschitz continuous third-order partial derivatives, Theorem~2.1.5 from \citet{nesterov2018book} implies that $\tilde L$ is $\beta$-smooth. For some tensor $B$ which captures all summands from the mean-zero perturbation of Eq.~\eqref{eq:writing_out_z_n_for_Ber} we have
\begin{align*}
    \tilde L(z_{n+1}) &\le \tilde L(z_{n}) +\langle\nabla \tilde L(z_{n}), z_{n+1} - z_{n}\rangle + \frac{\beta}{2}\|z_{n+1} - z_{n}\|^2\\
    &\overset{\eqref{eq:writing_out_z_n_for_Ber}}{=} \tilde L(z_{n}) -\eta\langle\nabla \tilde L(z_{n}),  \nabla \tilde L(z_n) + B(z_n)\odot \xi_n + O(\sigma^3)\rangle + \frac{\beta\eta^2}{2}\|\nabla \tilde L(z_n) + B(z_n) \odot \xi_n + O(\sigma^3)\|^2\\
    &= \tilde L(z_{n}) -\eta\|\nabla \tilde L(z_{n})\|^2 + \frac{\beta\eta^2}{2}\|\nabla \tilde L(z_n)\|^2\\
    &\quad -\eta\langle\nabla \tilde L(z_{n}), B(z_n)\odot \xi_n\rangle + \eta\langle\nabla \tilde L(z_{n}), O(\sigma^3)\rangle\\
    &  \quad + \frac{\beta\eta^2}{2}\left[\|B(z_n) \odot \xi_n\|^2 +O(\sigma^6)+ 2 \langle \nabla \tilde L(z_n) + O(\sigma^3), B(z_n) \odot \xi_n\rangle + 2 \langle \nabla \tilde L(z_n), O(\sigma^3)\rangle\right]
\end{align*}

Taking the expectation, most of the terms cancel out and we get
\begin{align}
   \mathbb{E}[\tilde L(z_{n+1})] \le
& \mathbb{E}\left[\tilde L(z_{n}) -\eta\|\nabla \tilde L(z_{n})\|^2 + \frac{\beta\eta^2}{2}\|\nabla \tilde L(z_n)\|^2\right]\\
&\quad + O(\eta\sigma^3)\\
&  \quad + \frac{\beta\eta^2}{2}\left[O(\sigma^2) +O(\sigma^6)+ O(\sigma^3)\right]\\   
&=\mathbb{E}[\tilde L(z_{n})] -\left(\eta-\frac{\beta\eta^2}{2}\right)\mathbb{E}[\|\nabla \tilde L(z_{n})\|^2] + O(\eta^2\sigma^2) +  O(\eta\sigma^3).
\end{align}
Note that, under the assumption of positive $\eta$,  $\left(\eta-\frac{\beta\eta^2}{2}\right)>0$ implies $0<\eta\le \frac{2}{\beta}$. If we further require  $\left(\eta-\frac{\beta\eta^2}{2}\right)\ge\frac{\eta}{2}$, we get the condition $0<\eta\le \frac{1}{\beta}$. 

Under this condition, the following upper bound holds\footnote{Outlined in blue color below is the updated version of the proof of the theorem.}:

\begin{equation}
   \mathbb{E}[\tilde L(z_{n+1})] \le \mathbb{E}[\tilde L(z_{n})] -\frac{\eta}{2}\mathbb{E}[\|\nabla \tilde L(z_{n})\|^2] + O(\eta^2\sigma^2) +  O(\eta\sigma^3).
\end{equation}

Rearranging the terms we get

\begin{equation}
    \frac{\eta}{2}\mathbb{E}[\|\nabla \tilde L(z_{n})\|^2] \le \mathbb{E}[\tilde L(z_{n})] - \mathbb{E}[\tilde L(z_{n+1})] + O(\eta^2\sigma^2) +  O(\eta\sigma^3).
\end{equation}
After a division by $\eta/2>0$ we arrive at

\begin{equation}
    \mathbb{E}[\|\nabla \tilde L(z_{n})\|^2] \le \frac{2}{\eta} \left(\mathbb{E}[\tilde L(z_{n})] - \mathbb{E}[\tilde L(z_{n+1})]\right) + O(\eta\sigma^2) +  O(\sigma^3).
\end{equation}

Summing all terms, we arrive at the following:

\begin{equation}
    \mathbb{E}\left[\sum_{n=0}^{N-1}\|\nabla \tilde L(z_{n})\|^2\right] \le \frac{2}{\eta} \left(\mathbb{E}[\tilde L(z_{0})] - \mathbb{E}[\tilde L(z_{N})]\right) + O(N\eta\sigma^2) +  O(N\sigma^3).
\end{equation}

After dividing by $N$ we get

\begin{equation}
    \mathbb{E}\left[\frac{1}{N}\sum_{n=0}^{N-1}\|\nabla \tilde L(z_{n})\|^2\right] \le \frac{2}{\eta N} \left(\mathbb{E}[\tilde L(z_{0})] - \mathbb{E}[\tilde L(z_{N})]\right) + O(\eta\sigma^2) +  O(\sigma^3).
\end{equation}

Note that $\tilde L(z_{N})\ge\tilde L^* = \min_z \tilde L(z) > -\infty$. This is because $L$ is lower bounded and also $tr(\nabla^2 L)$ is lower bounded since we assumed $L$ has Lipschitz gradients. Therefore, $\mathbb{E}[\tilde L(z_{0})] - \mathbb{E}[\tilde L(z_{N})] = O(1)$ and we conclude that

\begin{equation}
    \mathbb{E}\left[\frac{1}{N}\sum_{n=0}^{N-1}\|\nabla \tilde L(z_{n})\|^2\right] \le O(\eta^{-1} N^{-1}) + O(\eta\sigma^2) +  O(\sigma^3).
\end{equation}




If we set $\eta = O(\epsilon/\sigma^2)$, then $O(\eta\sigma^2) = O(\epsilon)$. Further, under the choice $\eta = \Theta(\epsilon/\sigma^2)$, we also have $O(\eta^{-1} N^{-1}) = O(\sigma^2 \epsilon^{-1}N^{-1})$. By setting $N = \Omega(\sigma^2\epsilon^{-2})$, we ensure that $O(\eta^{-1} N^{-1}) = O(\epsilon)$. 

All in all, we get $\mathbb{E}\left[\frac{1}{N}\sum_{n=0}^{N-1}\|\nabla \tilde L(z_{n})\|^2\right] \le O(\epsilon) + O(\sigma^3)$.

\label{lemma:variations}
Let $w\in\mathbb{R}^d$ evolve with time-varying linear dynamics $w_{k+1} = A_k w_k + \varepsilon_k$, where $A_k\in\mathbb{R}^{d\times d}$ and $\varepsilon_k\in \mathbb{R}^{d}$ for all $k$. Then, with the convention that $\prod_{j=k+1}^{k} A_j = 1$, 
\begin{equation}
    w_{k+1} = \left(\prod_{j=0}^{k}A_j\right)w_0 +\sum_{i=0}^{k}\left(\prod_{j=i+1}^{k} A_j\right)\varepsilon_i.
\end{equation}

\label{cor:anti_variations}
Under the same setting of Lemma~\ref{lemma:variations}, if there exist a family of vectors $\{\xi_k\}$ such that $\varepsilon_0 = \xi_0$ and $\varepsilon_k = \xi_k-\xi_{k-1}$, then
\begin{equation}
    w_{k+1} = \left(\prod_{j=0}^{k}A_j\right)w_0 +\xi_k  +\sum_{i=0}^{k-1}(A_{i+1}-I)\left(\prod_{j=i+2}^{k}  A_j\right)\xi_{i}.
\end{equation}

Let $w\in\mathbb{R}^d$ evolve with time-varying linear dynamics $w_{k+1} = A_k w_k + \varepsilon_k$, where $A_k\in\mathbb{R}^{d\times d}$ and $\varepsilon_k\in \mathbb{R}^{d}$ for all $k$. Let $\{\xi_k\}$ be a family of uncorrelated zero-mean $d$-dimensional random variables with variance $\mathbb{E}[\|\xi_k\|^2 ]= d\sigma^2$~(dependency on the dimension because additivity of squared norm). Consider $\varepsilon_0 = \xi_0$ and $\varepsilon_k = \xi_k-\xi_{k-1}$ for all $k\ge 1$. Further, assume that $A_k = \rho_k I$ for all $k$ (i.e. $A_k$ is a multiple of the identity), with $\rho_k\in\mathbb{R}$ a deterministic quantity. Then, with the convention that $\prod_{j=k+1}^{k} A_j = 1$, we have
\begin{equation}
    \mathbb{E}[\|w_{k+1}\|^2] = \left(\prod_{j=0}^{k}\rho_j^2\right) \|w_0\|^2 + \left(1+\sum_{i=0}^{k-1}\left[ (1-\rho_{i+1})^2 \prod_{j=i+2}^k \rho_j^2\right]\right)d \sigma^2. 
\end{equation}
Instead, if $\varepsilon_k = \xi_k$ for all $k$~(standard noise injection) we have
\begin{equation}
    \mathbb{E}[\|w_{k+1}\|^2] = \left(\prod_{j=0}^{k}\rho_j^2\right) \|w_0\|^2 + \sum_{i=0}^{k}\left(\prod_{j=i+1}^k \rho_j^2\right)d \sigma^2. 
\end{equation}
\label{prop:ito_discrete}

Using independence of the $\{\xi_k\}$ family, we obtain for the anticorrelated case:

    \begin{align}
    \mathbb{E}[w_{k+1}^\top w_{k+1}] &= \left(\prod_{j=0}^{k}\rho_j\right)^2\|w_0\|^2 +\mathbb{E}[\|\xi_k\|^2]  +\sum_{i=0}^{k-1}(\rho_{i+1}-1)^2\left(\prod_{j=i+2}^{k}  \rho_j\right)^2\mathbb{E}[\|\xi_{i}\|^2]\\
    &= \left(\prod_{j=0}^{k}\rho_j\right)^2\|w_0\|^2 +\sigma^2  +\sum_{i=0}^{k-1}(\rho_{i+1}-1)^2\left(\prod_{j=i+2}^{k}  \rho_j^2\right)\sigma^2,
    \end{align}
    where we used the fact that the $\xi_k$ are not correlated. The case $\varepsilon_k = \xi_k$ is similar and therefore left to the reader.

In the setting of Proposition~\ref{prop:ito_discrete}, assume $\rho_j = \rho \in (0,1)$ is constant for all $j$. If $\varepsilon_0 = \xi_0$ and $\varepsilon_k = \xi_k-\xi_{k-1}$ for all $k\ge 1$ then

\begin{equation}
    \mathbb{E}[\|w_{k+1}\|^2] = \rho^{2(k+1)} \|w_0\|^2 + \left(1+\frac{(1-\rho)^2(1-\rho^{2 (k+1)})}{1-\rho^2}\right)d \sigma^2 \quad\overset{\infty}{\longrightarrow}\quad  \frac{2}{1+\rho} d \sigma^2. 
\end{equation}

\noindent Instead, if $\varepsilon_k = \xi_k$ for all $k$~(standard noise injection) we have

\begin{equation}
    \mathbb{E}[\|w_{k+1}\|^2] = \rho^{2(k+1)} \|w_0\|^2 + \frac{1-\rho^{2 (k+1)}}{1-\rho^2} d \sigma^2\quad \overset{\infty}{\longrightarrow}\quad  \frac{1}{1-\rho^2} d \sigma^2.
\end{equation}
\label{cor:ito_discrete_const}

\label{prop:ito_discrete_all_rho}
Let $w\in\mathbb{R}^d$ evolve with time-varying linear dynamics $w_{k+1} = A_k w_k + \varepsilon_k$, where $A_k\in\mathbb{R}^{d\times d}$ and $\varepsilon_k\in \mathbb{R}^{d}$ for all $k$. Let $\{\xi_k\}$ be a family of uncorrelated zero-mean $d$-dimensional random variables with variance $\mathbb{E}[\|\xi_k\|^2 ]= d\sigma^2$~(dependency on the dimension because additivity of squared norm). Consider $\varepsilon_0 = \xi_0$ and $\varepsilon_k = \xi_k-\xi_{k-1}$ for all $k\ge 1$. Further, assume that $A_k = \rho_k I$ for all $k$ (i.e. $A_k$ is a multiple of the identity) and that $\rho_k\in[0,1]$ for all $k$. Assume that the probability of $\rho_k<1$ is non-zero, i.e. that $\rho_k\ne 1$ with non-vanishing probability. Then, we have
\begin{equation}
\lim_{k\to\infty}\mathbb{E}[\|w_{k+1}\|^2]\le 2d\sigma^2.
\end{equation}

The proof is based on an induction argument, starting from the equation in Proposition~\ref{prop:ito_discrete}:
\begin{equation}
    \mathbb{E}[\|w_{k+1}\|^2] = \left(\prod_{j=0}^{k}\rho_j^2\right) \|w_0\|^2 + \left(1+\sum_{i=0}^{k-1}\left[ (1-\rho_{i+1})^2 \prod_{j=i+2}^k \rho_j^2\right]\right)d \sigma^2. 
\end{equation}
First, note that by assumption on $\rho_k$ the first term vanishes as $k\to\infty$. We just have to deal with the second term. Specifically, we want to show that for whatever sequence $\rho_k\in(0,1)$ we have
\begin{equation}
    \nu_k = \sum_{i=0}^{k-1} (1-\rho_{i+1})^2 \left(\prod_{j=i+2}^k \rho_j^2\right)\le1, \ \quad \forall k\ge 0.
\end{equation}

A fundamental observation, is that the term can be written in a recursive form. Indeed,
\begin{align}
    \nu_k &= \sum_{i=0}^{k-1} \left[(1-\rho_{i+1})^2 \left(\prod_{j=i+2}^k \rho_j^2\right)\right]\\
    &= \sum_{i=0}^{k-2} \left[(1-\rho_{i+1})^2 \left(\prod_{j=i+2}^k \rho_j^2\right)\right] + (1-\rho_{k})^2\\
    &= \rho_k \sum_{i=0}^{k-2} \left[(1-\rho_{i+1})^2 \left(\prod_{j=i+2}^{k-1} \rho_j^2\right)\right] + (1-\rho_{k})^2\\
    & = \rho_k^2\nu_{k-1} + (1-\rho_k)^2,
\end{align}
where the second equality follows from the fact that, as previously noted, our notation implies $\prod_{j=k+1}^k \rho_k^2 = 1$, for all $k$. Let us now proceed again by induction to show that $v_k\in(0,1)$ for all $k\ge 0$. Note that trivially $v_0=0$. Let's proceed with the inductive step:
\begin{equation}
    \nu_k = \rho_k^2\nu_{k-1} + (1-\rho_k)^2 = (\nu_{k-1}+1)\rho_k^2 - 2\rho_k + 1.
\end{equation}
This quantity is less then one if and only if
\begin{equation}
 (\nu_{k-1}+1)\rho_k^2 \le 2\rho_k.
\end{equation}
Note that this is satisfied since $\nu_{k-1}+1\le2$, and $\rho_k^2 \le \rho_k$ since $\rho_k\in(0,1)$. The result follows.

As above, we denote the perturbations by $\varepsilon_k$; i.e., $\varepsilon_k = \xi_k$ for PGD and $\varepsilon_k = \xi_{k+1} - \xi_k$ for Anti-PGD.
Let us start by inspecting the equation
\begin{equation}
    u_{k+1} = (1 - \eta v_k^2) \cdot u_k + \varepsilon_{k}^u,
\end{equation}
where $\varepsilon_{k}^u\in\mathbb{R}^d$ is the projection of the noise $\varepsilon_{k}$ to the first $d$ coordinates.
It is clear that the optimal strategy of making $\|w\|$ small is to increase $|v|$, so to sample nearby points and pick up the gradient. The greater $v$ is in norm, the better. We can increase the norm of $v$ by heavy noise injection~(second equation). However, too much noise also increases $\varepsilon_{k}^u$, which acts adversarially to the decrease of $\|w\|$~(error accumulation increases the Euclidean norm in expectation).

